316	/**
317	 * One SPA web part shell — HashRouter + keep-alive + feature lazy entries.
318	 */
319	export default function HhhhSpaApp(props: IHhhhSpaProps): React.ReactElement<IHhhhSpaProps> {
320	  const pageProps = React.useMemo(
321	    () => ({
322	      ...props,
323	      AdminconfigrationID: props.AdminConfigrationListID,
324	      AdminConfigrationListID: props.AdminConfigrationListID,
325	      dropdownvalue: 'Component Portfolio'
326	    }),
327	    [props]
328	  );
329	
330	  return (
331	    <HashRouter>
332	      <SpaNavigationInterceptor />
333	      {/* hhhh-spa-webpart: Style.css body rules are compiled to this selector for SPFx */}
334	      <div className={`hhhh-spa-webpart ${styles.hhhhSpaShell}`} style={{ flexDirection: 'column' }}>
335	        <div style={{ flex: '0 0 auto', width: '100%' }}>
336	          <SpaTopNavigation siteUrl={props.siteUrl} context={props.Context} />
337	        </div>
338	        <div style={{ display: 'flex', flex: '1 1 auto', minHeight: 0, minWidth: 0, width: '100%' }}>
339	          <SpaLeftNavigation>
340	            <SpaBreadcrumb />
341	            <FeatureOutlet pageProps={pageProps} />
342	          </SpaLeftNavigation>
343	        </div>
344	      </div>
345	    </HashRouter>
346	  );
347	}
