import * as React from 'react';
import DashboardComponent from '../../pages/dashboard/components/DashboardComponent';
import type { ISpaFeatureProps } from '../../shared/spa/types';

export default function DashboardFeature(props: ISpaFeatureProps): React.ReactElement {
  const rawSiteUrl = String(
    props.pageProps?.siteUrl ||
    props.pageProps?.Context?.pageContext?.web?.absoluteUrl ||
    ''
  ).replace(/\/+$/, '');
  const normalizedSiteUrl = /\/sp$/i.test(rawSiteUrl)
    ? rawSiteUrl
    : rawSiteUrl
    ? `${rawSiteUrl}/SP`
    : rawSiteUrl;

  return <DashboardComponent props={{ ...props.pageProps, siteUrl: normalizedSiteUrl }} />;
}

